import { createProject } from '../test-utils'

describe('@fluent-disable-sync directive', () => {
    const changes = {
        path: 'changes.xml',
        content: `
        <?xml version="1.0"?>
        <unload>
            <test_table action="INSERT_OR_UPDATE">
                <sys_id>12345</sys_id>
                <name>Changed!</name>
            </test_table>
        </unload>
        `,
    }

    test('prevents updating a CallExpression on transform [ExpressionStatement]', async () => {
        const project = createProject({
            rootDir: __dirname,
        })

        project.registerExplicitId('test_table', 'test', '12345')
        project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `
            import { Record } from '@servicenow/sdk/core'

            // @fluent-disable-sync Can add a comment after directive
            Record({
                $id: Now.ID['test'],
                table: 'test_table',
                data: {
                    name: 'Original Value'
                }
            })
            `,
        })

        const output = await project.transform(changes)
        expect(output.changedFiles).toHaveLength(0)
        expect(await project.getDiagnostics()).toHaveLength(0)
    })

    test('prevents updating a CallExpression on transform, even when using /* C */ style comments', async () => {
        const project = createProject({
            rootDir: __dirname,
        })
        project.registerExplicitId('test_table', 'test', '12345')

        project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `
            import { Record } from '@servicenow/sdk/core'

            /* @fluent-disable-sync */
            Record({
                $id: Now.ID['test'],
                table: 'test_table',
                data: {
                    name: 'Original Value'
                }
            })
            `,
        })

        const output = await project.transform(changes)
        expect(output.changedFiles).toHaveLength(0)
        expect(await project.getDiagnostics()).toHaveLength(0)
    })

    test('prevents updating a CallExpression on transform, even when using /* C */ style comments on multiple lines', async () => {
        const project = createProject({
            rootDir: __dirname,
        })
        project.registerExplicitId('test_table', 'test', '12345')

        project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `
            import { Record } from '@servicenow/sdk/core'

            /*
                @author Bob Barker
                @fluent-disable-sync
            */
            Record({
                $id: Now.ID['test'],
                table: 'test_table',
                data: {
                    name: 'Original Value'
                }
            })
            `,
        })

        const output = await project.transform(changes)
        expect(output.changedFiles).toHaveLength(0)
        expect(await project.getDiagnostics()).toHaveLength(0)
    })

    test('prevents updating a CallExpression on transform [VariableDeclaration]', async () => {
        const project = createProject({
            rootDir: __dirname,
        })
        project.registerExplicitId('test_table', 'test', '12345')

        project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `
            import { Record } from '@servicenow/sdk/core'

            // @fluent-disable-sync
            export const record = Record({
                $id: Now.ID['test'],
                table: 'test_table',
                data: {
                    name: 'Original Value'
                }
            })
            `,
        })

        const output = await project.transform(changes)
        expect(output.changedFiles).toHaveLength(0)
        expect(await project.getDiagnostics()).toHaveLength(0)
    })

    test('prevents updating a CallExpression on transform [exported VariableDeclaration]', async () => {
        const project = createProject({
            rootDir: __dirname,
        })
        project.registerExplicitId('test_table', 'test', '12345')

        project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `
            import { Record } from '@servicenow/sdk/core'

            // @fluent-disable-sync
            export const record = Record({
                $id: Now.ID['test'],
                table: 'test_table',
                data: {
                    name: 'Original Value'
                }
            })
            `,
        })

        const output = await project.transform(changes)
        expect(output.changedFiles).toHaveLength(0)
        expect(await project.getDiagnostics()).toHaveLength(0)
    })

    test('prevents updating a CallExpression on transform [ExportAssignment]', async () => {
        const project = createProject({
            rootDir: __dirname,
        })
        project.registerExplicitId('test_table', 'test', '12345')

        project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `
            import { Record } from '@servicenow/sdk/core'

            // @fluent-disable-sync
            export default Record({
                $id: Now.ID['test'],
                table: 'test_table',
                data: {
                    name: 'Original Value'
                }
            })
            `,
        })

        const output = await project.transform(changes)
        expect(output.changedFiles).toHaveLength(0)
        expect(await project.getDiagnostics()).toHaveLength(0)
    })

    test('prevents updating a nested CallExpression on transform', async () => {
        const project = createProject({
            rootDir: __dirname,
        })
        project.registerCoalesceId('sys_user_role', { name: 'x_test.parent_role' }, '12345')
        project.registerCoalesceId('sys_user_role', { name: 'x_test.child_role' }, '54321')

        project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `
            import { Role } from '@servicenow/sdk/core'

            Role({
                name: 'x_test.parent_role',
                containsRoles: [
                    // @fluent-disable-sync
                    Role({
                        name: 'x_test.child_role',
                    })
                ]
            })
            `,
        })

        const changes = {
            path: 'changes.xml',
            content: `
            <?xml version="1.0"?>
            <unload>
                <sys_user_role action="INSERT_OR_UPDATE">
                    <sys_id>54321</sys_id>
                    <name>x_test.child_role</name>
                    <suffix>child_role</suffix>
                    <description>child_role_description</description>
                </sys_user_role>
            </unload>
            `,
        }
        const output = await project.transform(changes)
        expect(output.changedFiles).toHaveLength(0)
        expect(await project.getDiagnostics()).toHaveLength(0)
    })

    test('does NOT prevent updating a parent CallExpression when a child has the directive', async () => {
        const project = createProject({
            rootDir: __dirname,
        })
        project.registerCoalesceId('sys_user_role', { name: 'x_test.parent_role' }, '12345')
        project.registerCoalesceId('sys_user_role', { name: 'x_test.child_role' }, '54321')

        project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `
            import { Role } from '@servicenow/sdk/core'

            Role({
                name: 'x_test.parent_role',
                contains_roles: [
                    // @fluent-disable-sync
                    Role({
                        name: 'x_test.child_role',
                    })
                ]
            })
            `,
        })

        const changes = {
            path: 'changes.xml',
            content: `
            <?xml version="1.0"?>
            <unload>
                <sys_user_role action="INSERT_OR_UPDATE">
                    <sys_id>12345</sys_id>
                    <name>x_test.parent_role</name>
                    <suffix>parent_role</suffix>
                    <description>parent_role_description</description>
                </sys_user_role>
            </unload>
            `,
        }
        const output = await project.transform(changes)
        expect(output.changedFiles).toHaveLength(1)
        expect(await project.getDiagnostics()).toHaveLength(0)
        expect(output.changedFiles.find((f) => f.getName() === 'index.now.ts').getContent()).toMatchInlineSnapshot(`
"import { Role } from '@servicenow/sdk/core'

Role({
    name: 'x_test.parent_role',
    containsRoles: [
        // @fluent-disable-sync
        Role({
            name: 'x_test.child_role',
        }),
    ],
    description: 'parent_role_description',
})
"
`)
    })

    test('Prevents updates to a child [PropertyAssignment] with the directive, but not siblings or the parent', async () => {
        const project = createProject({
            rootDir: __dirname,
        })
        project.registerExplicitId('test_table', 'test', '12345')

        project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `
            import { Record } from '@servicenow/sdk/core'

            Record({
                $id: Now.ID['test'],
                table: 'test_table',
                data: {
                    before: 123,
                    // @fluent-disable-sync
                    name: 'Original Value',
                    after: 'abc',
                }
            })
            `,
        })

        const output = await project.transform({
            path: 'changes.xml',
            content: `
        <?xml version="1.0"?>
        <unload>
            <test_table action="INSERT_OR_UPDATE">
                <sys_id>12345</sys_id>
                <before>789</before>
                <name>Changed!</name>
                <after>xyz</after>
            </test_table>
        </unload>
        `,
        })

        expect(output.changedFiles).toHaveLength(1)
        expect(output.changedFiles.find((f) => f.getName() === 'index.now.ts').getContent()).toMatchInlineSnapshot(`
"import { Record } from '@servicenow/sdk/core'

Record({
    $id: Now.ID['test'],
    table: 'test_table',
    data: {
        before: 789,
        // @fluent-disable-sync
        name: 'Original Value',
        after: 'xyz',
    },
})
"
`)
    })

    test('prevents transforming the entire file if located at the top of the file', async () => {
        const project = createProject({
            rootDir: __dirname,
        })
        project.registerExplicitId('test_table', 'test', '12345')

        project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `
            // @fluent-disable-sync-for-file Extra comments allowed afterward!
            import { Record } from '@servicenow/sdk/core'

            Record({
                $id: Now.ID['test'],
                table: 'test_table',
                data: {
                    name: 'Original Value'
                }
            })
            `,
        })

        const output = await project.transform(changes)
        expect(output.changedFiles).toHaveLength(0)
        expect(await project.getDiagnostics()).toHaveLength(0)
    })

    test('prevents transforming the entire file if located at the top of the file (multi-line comment)', async () => {
        const project = createProject({
            rootDir: __dirname,
        })
        project.registerExplicitId('test_table', 'test', '12345')

        project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `
            /*
            Extra comments allowed before!
            
            @fluent-disable-sync-for-file
            
            Extra comments allowed afterward!
            */
            import { Record } from '@servicenow/sdk/core'

            Record({
                $id: Now.ID['test'],
                table: 'test_table',
                data: {
                    name: 'Original Value'
                }
            })
            `,
        })

        const output = await project.transform(changes)
        expect(output.changedFiles).toHaveLength(0)
        expect(await project.getDiagnostics()).toHaveLength(0)
    })
})
